def transform(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    one=two=None
    for r in range(h):
        for c in range(w):
            if g[r][c]==1: one=(r,c)
            if g[r][c]==2: two=(r,c)
    (r1,c1),(r2,c2)=one,two
    sr=1 if r2>r1 else -1; sc=1 if c2>c1 else -1
    r,c=r1,c1
    # diagonal until one short of 2's row or 2's col (whichever first)
    while r!=r2-sr and c!=c2-sc:
        r+=sr; c+=sc
        if g[r][c]==0: g[r][c]=3
    # straight along remaining axis toward 2 until one short
    if r==r2-sr:  # row fixed, move col
        while c!=c2-sc:
            c+=sc
            if g[r][c]==0: g[r][c]=3
    else:
        while r!=r2-sr:
            r+=sr
            if g[r][c]==0: g[r][c]=3
    # final diagonal step into 2
    r+= (1 if r2>r else -1) if r!=r2 else 0
    c+= (1 if c2>c else -1) if c!=c2 else 0
    return g

